39	#[cfg(test)]
40	mod bench;
41	
42	use docopt::Docopt;
43	use rayon::prelude::*;
44	use std::time::{Duration, Instant};
45	
46	const CHUNK_SIZE: usize = 100_000;
47	
48	// Number of Primes < 10^n
49	// https://oeis.org/A006880
50	const NUM_PRIMES: &[usize] = &[
51	    0,  // primes in 0..10^0
52	    4,  // primes in 0..10^1
53	    25, // etc
54	    168,
55	    1_229,
56	    9_592,
57	    78_498,
58	    664_579,
59	    5_761_455,
60	    50_847_534,
61	    455_052_511,
62	    4_118_054_813,
63	    37_607_912_018,
64	    346_065_536_839,
65	    3_204_941_750_802,
66	    29_844_570_422_669,
67	    279_238_341_033_925,
68	    2_623_557_157_654_233,
69	    24_739_954_287_740_860,
70	    234_057_667_276_344_607,
71	    2_220_819_602_560_918_840,
72	];
73	
74	// For all of these sieves, sieve[i]==true -> 2*i+1 is prime
75	
76	fn max(magnitude: usize) -> usize {
77	    10_usize.pow(magnitude as u32)
78	}
79	
80	/// Sieve odd integers for primes < max.
81	fn sieve_serial(max: usize) -> Vec<bool> {
82	    let mut sieve = vec![true; max / 2];
83	    sieve[0] = false; // 1 is not prime
84	    for i in 1.. {
85	        if sieve[i] {
86	            let p = 2 * i + 1;
87	            let pp = p * p;
88	            if pp >= max {
89	                break;
90	            }
91	            clear_stride(&mut sieve, pp / 2, p);
92	        }
93	    }
94	    sieve
95	}
96	
97	/// Sieve odd integers for primes < max using chunks.
98	fn sieve_chunks(max: usize) -> Vec<bool> {
99	    // first compute the small primes, up to sqrt(max).
100	    let small_max = (max as f64).sqrt().ceil() as usize;
101	    let mut sieve = sieve_serial(small_max);
102	    sieve.resize(max / 2, true);
103	
104	    {
105	        let (low, high) = sieve.split_at_mut(small_max / 2);
106	        for (chunk_index, chunk) in high.chunks_mut(CHUNK_SIZE).enumerate() {
107	            let i = small_max / 2 + chunk_index * CHUNK_SIZE;
108	            let base = i * 2 + 1;
109	            update_chunk(low, chunk, base);
110	        }
111	    }
112	
113	    sieve
114	}
115	
116	/// Sieve odd integers for primes < max, in parallel!
117	fn sieve_parallel(max: usize) -> Vec<bool> {
118	    // first compute the small primes, up to sqrt(max).
119	    let small_max = (max as f64).sqrt().ceil() as usize;
120	    let mut sieve = sieve_serial(small_max);
121	    sieve.resize(max / 2, true);
122	
123	    {
124	        let (low, high) = sieve.split_at_mut(small_max / 2);
125	        high.par_chunks_mut(CHUNK_SIZE)
126	            .enumerate() // to figure out where this chunk came from
127	            .with_max_len(1) // ensure every single chunk is a separate rayon job
128	            .for_each(|(chunk_index, chunk)| {
129	                let i = small_max / 2 + chunk_index * CHUNK_SIZE;
130	                let base = i * 2 + 1;
131	                update_chunk(low, chunk, base);
132	            });
133	    }
134	
135	    sieve
136	}
137	
138	/// Update a chunk with low primes
139	fn update_chunk(low: &[bool], chunk: &mut [bool], base: usize) {
140	    let max = base + chunk.len() * 2;
141	    for (i, &is_prime) in low.iter().enumerate() {
142	        if is_prime {
143	            let p = 2 * i + 1;
144	            let pp = p * p;
145	            if pp >= max {
146	                break;
147	            }
148	
149	            let pm = if pp < base {
150	                // p² is too small - find the first odd multiple that's in range
151	                (base.div_ceil(p) | 1) * p
152	            } else {
153	                pp
154	            };
155	
156	            if pm < max {
157	                clear_stride(chunk, (pm - base) / 2, p);
158	            }
159	        }
160	    }
161	}
162	
163	fn clear_stride(slice: &mut [bool], from: usize, stride: usize) {
164	    slice[from..]
165	        .iter_mut()
166	        .step_by(stride)
167	        .for_each(|x| *x = false)
168	}
