171	    const MAGNITUDE: usize = 9;
172	
173	    let start = Instant::now();
174	    let sieve = f(max(MAGNITUDE));
175	    let duration = start.elapsed();
176	
177	    // sanity check the number of primes found
178	    let num_primes = 1 + sieve.into_iter().filter(|&b| b).count();
179	    assert_eq!(num_primes, NUM_PRIMES[MAGNITUDE]);
180	
181	    duration
182	}
