185	    let args: Args = Docopt::new(USAGE)
186	        .and_then(|d| d.argv(args).deserialize())
187	        .unwrap_or_else(|e| e.exit());
188	
189	    if args.cmd_bench {
190	        let serial = measure(sieve_serial).as_nanos();
191	        println!("  serial: {serial:10} ns");
192	
193	        let chunks = measure(sieve_chunks).as_nanos();
194	        println!(
195	            "  chunks: {:10} ns -> {:.2}x speedup",
196	            chunks,
197	            serial as f64 / chunks as f64
198	        );
199	
200	        let parallel = measure(sieve_parallel).as_nanos();
201	        println!(
202	            "parallel: {:10} ns -> {:.2}x speedup",
203	            parallel,
